    r0, r1 = min(r for r, c in cells), max(r for r, c in cells)
    c0, c1 = min(c for r, c in cells), max(c for r, c in cells)
    markers = {(r, c) for r in range(h) for c in range(w)
               if grid[r][c] not in (0, 2)}
    # Extend the rectangle's rows toward the grid edges, except toward markers.
    for r in range(r0, r1 + 1):
        left_blocked = any(rr == r and cc < c0 for rr, cc in markers)
        right_blocked = any(rr == r and cc > c1 for rr, cc in markers)
        if not left_blocked:
            for c in range(c0):
                if grid[r][c] == 0: out[r][c] = 2
        if not right_blocked:
            for c in range(c1 + 1, w):
                if grid[r][c] == 0: out[r][c] = 2
    # Extend its columns vertically, except toward markers.
    for c in range(c0, c1 + 1):
        top_blocked = any(cc == c and rr < r0 for rr, cc in markers)
        bottom_blocked = any(cc == c and rr > r1 for rr, cc in markers)
        if not top_blocked:
            for r in range(r0):
                if grid[r][c] == 0: out[r][c] = 2
        if not bottom_blocked:
            for r in range(r1 + 1, h):
                if grid[r][c] == 0: out[r][c] = 2
    return out
